/**
 * VirtueMart constants.
 *
 * VirtueMart is a Joomla CMS ecommerce extension. It documents no REST or JSON
 * web-service API: https://docs.virtuemart.net/vm-api says "The VirtueMart API
 * documentation is generated by the tool Doxygen." (a PHP code reference).
 * Every read method refuses with 501; see index.ts.
 *
 * Credentials (unchanged): `accessToken` and `extra.baseUrl`. VirtueMart
 * documents no API token; the Joomla frontend authenticates by session.
 *
 * Slug: `virtuemart`
 */

/** Joomla component query param for VirtueMart views. */
export const JOOMLA_OPTION = 'com_virtuemart'
export const JOOMLA_FORMAT = 'json'

/** VirtueMart order status codes. */
export const VM_STATUS_CONFIRMED = 'C'
export const VM_STATUS_PENDING = 'P'
export const VM_STATUS_SHIPPED = 'S'
export const VM_STATUS_CANCELLED = 'X'
export const VM_STATUS_REFUNDED = 'R'
export const VM_STATUS_UNCONFIRMED = 'U'

/**
 * Undocumented currency fallback, used only by transformOrder for the
 * out-of-scope cancelOrder write. Recorded for the lead; no read path uses it.
 */
export const DEFAULT_CURRENCY = 'EUR'
